package com.italiano2774.nativeapp;
import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class ListeningCourseRepository{
 private static ListeningCourseRepository instance;private final List<ListeningCourse> all=new ArrayList<>();
 private ListeningCourseRepository(Context c){try(BufferedReader br=new BufferedReader(new InputStreamReader(c.getAssets().open("listening_courses.json"),StandardCharsets.UTF_8))){StringBuilder sb=new StringBuilder();String line;while((line=br.readLine())!=null)sb.append(line);JSONArray a=new JSONArray(sb.toString());for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);ListeningCourse x=new ListeningCourse();x.id=o.optString("id");x.level=o.optString("level");x.title=o.optString("title");x.subtitle=o.optString("subtitle");x.wpm=o.optInt("wpm",90);JSONArray ss=o.optJSONArray("sentences");if(ss!=null)for(int j=0;j<ss.length();j++){JSONObject q=ss.getJSONObject(j);ListeningSentence s=new ListeningSentence();s.id=q.optString("id",x.id+"_"+j);s.italian=q.optString("it");s.chinese=q.optString("zh");s.category=q.optString("category");s.note=q.optString("note");x.sentences.add(s);}all.add(x);}}catch(Exception e){throw new RuntimeException("Failed to load listening_courses.json",e);}}
 public static synchronized ListeningCourseRepository get(Context c){if(instance==null)instance=new ListeningCourseRepository(c.getApplicationContext());return instance;}
 public List<ListeningCourse> all(){return new ArrayList<>(all);}public List<ListeningCourse> level(String l){List<ListeningCourse> out=new ArrayList<>();for(ListeningCourse x:all)if(l==null||l.isEmpty()||l.equals(x.level))out.add(x);return out;}public ListeningCourse find(String id){for(ListeningCourse x:all)if(x.id.equals(id))return x;return null;}
}
